// Общий код для качества соединения в звонке (#51da2a, b28a22ed6a85bb764151da2a; кейсы CQ-001…CQ-003).
// Логика клиента (бандл 14.10): замер getStats раз в 2 с; delay_ms = RTT/2 + средний jitterBufferDelay;
// замер «плохой», если потери > 20 % или delay_ms > 400; окно 10 с, ≥ 3 замера и охват ≥ 6 с;
// плашка — при ≥ 60 % плохих замеров, снимается — при ≤ 20 %. При включении плашки — candidate_record_event connection_warning.
// При конце звонка в end-candidate-attempt уходит recording_quality {input_level, packet_loss, latency_ms (max RTT)}.
import { BrowserContext, Page, Route } from '@playwright/test';
import { randomUUID } from 'crypto';
import { expect } from '../../fixtures';

export const WARNING = 'החיבור חלש כרגע. השיחה ממשיכה, אבל ייתכן שהקול ייקטע.';
export const LIVE_STATUS = /מחובר · הלקוח מקשיב|הלקוח מדבר/;

/** Плашка на экране звонка (data-testid из бандла, role=alert). */
export const warningBanner = (page: Page) => page.getByTestId('connection-warning');

/**
 * Наблюдатель плашки «החיבור חלש»: сколько раз появлялась и сколько миллисекунд была на экране.
 * Ставить на контекст ДО перехода по ссылке кандидата.
 */
export async function watchWarning(ctx: BrowserContext) {
  await ctx.addInitScript(() => {
    const w = { count: 0, onSince: 0, totalMs: 0, on: false };
    (window as unknown as { __qaWarn: typeof w }).__qaWarn = w;
    const check = () => {
      const on = !!document.querySelector('[data-testid="connection-warning"]');
      if (on && !w.on) {
        w.count++;
        w.onSince = Date.now();
      }
      if (!on && w.on) w.totalMs += Date.now() - w.onSince;
      w.on = on;
    };
    new MutationObserver(check).observe(document, { childList: true, subtree: true });
  });
}

export async function warningStats(page: Page) {
  return page.evaluate(() => {
    const w = (window as unknown as { __qaWarn: { count: number; onSince: number; totalMs: number; on: boolean } }).__qaWarn;
    return { count: w.count, totalMs: w.totalMs + (w.on ? Date.now() - w.onSince : 0), on: w.on };
  });
}

/** Запросы candidate_record_event с kind=connection_warning (настоящие или подменённые). */
export function trackWarningEvents(page: Page) {
  const events: Record<string, unknown>[] = [];
  page.on('request', (r) => {
    if (r.method() !== 'POST' || !r.url().includes('/rest/v1/rpc/candidate_record_event')) return;
    try {
      const b = r.postDataJSON() as { p_kind?: string; p_payload?: Record<string, unknown> };
      if (b?.p_kind === 'connection_warning') events.push(b.p_payload || {});
    } catch {
      /* не JSON — не наше событие */
    }
  });
  return events;
}

// ---------- Подмены для проверки логики без звонка (CQ-002, CQ-003) ----------

export type Net = { rttMs: number; jbMs: number; lossPct: number };

/**
 * Подменённый RTCPeerConnection: канал данных открывается сразу после setRemoteDescription, соединение «connected»,
 * getStats отдаёт накопительные счётчики (100 пакетов на замер) по window.__qaNet {rttMs, jbMs, lossPct}.
 * Сети и OpenAI нет. Ставить на контекст ДО перехода по ссылке (заменяет обёртку из launchCandidate).
 */
export async function fakePeer(ctx: BrowserContext, start: Net) {
  // Скрипт — строкой JS: функция не проходит через транспиляцию (хелперы полей классов в браузере недоступны).
  const content = `(() => {
    const net = Object.assign({ calls: 0 }, ${JSON.stringify(start)});
    window.__qaNet = net;
    const tot = { lost: 0, recv: 0, jd: 0, je: 0 };
    class FakeChannel extends EventTarget {
      constructor(label) { super(); this.label = label; this.readyState = 'connecting'; }
      send() {}
      close() {
        if (this.readyState === 'closed') return;
        this.readyState = 'closed';
        this.dispatchEvent(new Event('close'));
      }
    }
    class FakePeer extends EventTarget {
      constructor() { super(); this.connectionState = 'new'; this.ontrack = null; this.ch = null; }
      addTrack() { return {}; }
      createDataChannel(label) { this.ch = new FakeChannel(label); return this.ch; }
      async createOffer() { return { type: 'offer', sdp: 'v=0\\r\\n' }; }
      async setLocalDescription() {}
      async setRemoteDescription() {
        setTimeout(() => {
          this.connectionState = 'connected';
          this.dispatchEvent(new Event('connectionstatechange'));
          if (this.ch) { this.ch.readyState = 'open'; this.ch.dispatchEvent(new Event('open')); }
        }, 50);
      }
      async getStats() {
        net.calls++;
        const n = 100;
        const lost = Math.round((n * net.lossPct) / 100);
        tot.lost += lost; tot.recv += n - lost; tot.je += n; tot.jd += (n * net.jbMs) / 1000;
        const report = new Map();
        report.set('in', { type: 'inbound-rtp', kind: 'audio', packetsLost: tot.lost, packetsReceived: tot.recv, jitterBufferDelay: tot.jd, jitterBufferEmittedCount: tot.je });
        report.set('cp', { type: 'candidate-pair', state: 'succeeded', nominated: true, currentRoundTripTime: net.rttMs / 1000 });
        return report;
      }
      close() { this.connectionState = 'closed'; if (this.ch) this.ch.close(); }
    }
    window.RTCPeerConnection = FakePeer;
  })();`;
  await ctx.addInitScript({ content });
}

/** Сменить условия сети подменённого getStats; вернуть число замеров на этот момент. */
export async function setNet(page: Page, n: Partial<Net>): Promise<number> {
  return page.evaluate((v) => {
    const net = (window as unknown as { __qaNet: Net & { calls: number } }).__qaNet;
    Object.assign(net, v);
    return net.calls;
  }, n);
}

export const statsCalls = (page: Page) => page.evaluate(() => (window as unknown as { __qaNet: { calls: number } }).__qaNet.calls);

const FAKE_SDP_HOST = 'https://qa-fake-realtime.test';
const FAKE_UPLOAD_HOST = 'https://qa-fake-upload.test';

function cors(route: Route) {
  const h = route.request().headers();
  return {
    'access-control-allow-origin': h['origin'] || '*',
    'access-control-allow-headers': h['access-control-request-headers'] || '*',
    'access-control-allow-methods': 'GET, POST, PUT, OPTIONS',
  };
}

async function json(route: Route, body: unknown, status = 200) {
  if (route.request().method() === 'OPTIONS') return route.fulfill({ status: 200, headers: cors(route), body: 'ok' });
  return route.fulfill({ status, headers: { ...cors(route), 'content-type': 'application/json' }, body: JSON.stringify(body) });
}

export type Mocked = { start: number; voice: number; sdp: number; ended: number; openai: number; attemptId: string };

/**
 * Звонок без звонка: подменяет старт официальной попытки, голосовую сессию, обмен SDP, загрузку частей записи,
 * события и конец попытки. Настоящая попытка не создаётся, OpenAI не вызывается (api.openai.com — обрыв и счёт).
 */
export async function mockCallBackend(page: Page, maxSeconds = 180): Promise<Mocked> {
  const m: Mocked = { start: 0, voice: 0, sdp: 0, ended: 0, openai: 0, attemptId: randomUUID() };
  const post = (r: Route) => r.request().method() === 'POST';
  await page.route('https://api.openai.com/**', (r) => {
    m.openai++;
    return r.abort('failed');
  });
  await page.route('**/rest/v1/rpc/candidate_start_attempt', (r) => {
    if (post(r)) m.start++;
    return json(r, { status: 'in_progress', attempt_id: m.attemptId, attempt_type: 'official' });
  });
  await page.route('**/functions/v1/start-voice-session', (r) => {
    if (post(r)) m.voice++;
    return json(r, {
      max_duration_seconds: maxSeconds,
      session: { protocol: 'webrtc_sdp', connect_url: `${FAKE_SDP_HOST}/v1/realtime/calls`, client_secret: 'qa-fake', data_channel: 'oai-events' },
    });
  });
  await page.route(`${FAKE_SDP_HOST}/**`, (r) => {
    if (r.request().method() === 'OPTIONS') return r.fulfill({ status: 200, headers: cors(r), body: 'ok' });
    m.sdp++;
    return r.fulfill({ status: 201, headers: { ...cors(r), 'content-type': 'application/sdp' }, body: 'v=0\r\n' });
  });
  await page.route('**/functions/v1/recording-upload-url', (r) =>
    json(r, { path: `qa-fake/${m.attemptId}/parts/000000.webm`, upload_url: `${FAKE_UPLOAD_HOST}/part`, upload_headers: {} }),
  );
  await page.route(`${FAKE_UPLOAD_HOST}/**`, (r) => r.fulfill({ status: 200, headers: cors(r), body: '' }));
  await page.route('**/rest/v1/rpc/candidate_record_event', (r) => json(r, {}));
  await page.route('**/functions/v1/end-candidate-attempt', (r) => {
    if (post(r)) m.ended++;
    return json(r, { attempt: { status: 'completed' } });
  });
  return m;
}

/** Экран звонка «live»: таймер, статус соединения, «לסיים שיחה». */
export async function expectLive(page: Page) {
  await expect(page.getByTestId('call-stage')).toHaveAttribute('data-phase', 'live', { timeout: 60_000 });
  await expect(page.getByRole('timer')).toBeVisible();
  await expect(page.getByRole('status').filter({ hasText: LIVE_STATUS })).toBeVisible();
  await expect(page.getByRole('button', { name: 'לסיים שיחה' })).toBeVisible();
}

/** Дождаться, пока клиент сделает ещё `n` замеров getStats (раз в 2 с) — без фиксированных пауз. */
export async function waitSamples(page: Page, from: number, n: number) {
  await expect
    .poll(() => statsCalls(page), { message: `нет ${n} новых замеров getStats`, timeout: n * 2_000 + 15_000 })
    .toBeGreaterThanOrEqual(from + n);
}
